import{_ as l,c as i,o as a,ah as e}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"《序卦传》简介","description":"易传 - 《序卦传》简介","frontmatter":{"title":"《序卦传》简介","description":"易传 - 《序卦传》简介"},"headers":[],"relativePath":"zh/classics/yizhuan/005.md","filePath":"zh/classics/yizhuan/005.md"}'),t={name:"zh/classics/yizhuan/005.md"};function s(r,p,n,c,_,o){return a(),i("div",null,[...p[0]||(p[0]=[e('<h1 id="《序卦传》简介" tabindex="-1">《序卦传》简介 <a class="header-anchor" href="#《序卦传》简介" aria-label="Permalink to “《序卦传》简介”">​</a></h1><p>《序卦传》主要对《周易》六十四卦的排列顺序进行解说。其功能作用在于揭示各卦之间的推衍关系，将其视为一个因果联系序列进行诠释，有助于理解卦象之间的逻辑联系和宇宙间、人事间事物发展变化的规律。这为学习易经提供了重要的指导，有助于深入理解其哲学思想。</p><p>序卦传</p><p>有天地，然后万物生焉。盈天地之间者唯万物，故受之以《屯》。屯者，盈也。屯者，物之始生也。物生必蒙，故受之以《蒙》。蒙者，蒙也，物之稚也。</p><p>物稚不可不养也，故受之以《需》。需者，饮食之道也。饮食必有讼，故受之以《讼》。讼必有众起，故受之以《师》。师者，众也。众必有所比，故受之以《比》。比者，比也。比必有所畜，故受之以《小畜》。物畜然后有礼，故受之以《履》。履而泰，然后安，故受之以《泰》。泰者，通也。物不可以终通，故受之以《否》。物不可以终否，故受之以《同人》。与人同者，物必归焉，故受之以《大有》。有大者，不可以盈，故受之以《谦》。有大而能谦必豫，故受之以《豫》。豫必有随，故受之以《随》。以喜随人者必有事，故受之以《蛊》。</p><p>蛊者，事也。有事而后可大，故受之以《临》。临者，大也。物大然后可观，故受之以《观》。可观而后有所合，故受之以《噬嗑》。嗑者，合也。物不可以苟合而已，故受之以《贲》。贲者，饰也。致饰然后亨则尽矣，故受之以《剥》。</p><p>剥者，剥也。物不可以终尽剥，穷上反下，故受之以《复》。复则不妄矣，故受之以《无妄》。有无妄，物然后可畜，故受之以《大畜》。物畜然后可养，故受之以《颐》。颐者，养也。不养则不可动，故受之以《大过》。物不可以终过，故受之以《坎》。坎者，陷也。陷必有所丽，故受之以《离》。离者，丽也。</p><p>有天地然后有万物，有万物然后有男女，有男女然后有夫妇，有夫妇然后有父子，有父子然后有君臣，有君臣然后有上下，有上下然后礼义有所错。夫妇之道不可以不久也，故受之以《恒》。恒者，久也。物不可以久居其所，故受之以《遯》。遯者，退也。物不可以终遯，故受之以《大壮》。物不可以终壮，故受之以《晋》。晋者，进也。进必有所伤，故受之以《明夷》。夷者，伤也。伤于外者必反于家，故受之以《家人》。家道穷必乖，故受之以《睽》。睽者，乖也。</p><p>乖必有难，故受之以《蹇》。蹇者，难也。物不可以终难，故受之以《解》。解者，缓也。缓必有所失，故受之以《损》。损而不已必益，故受之以《益》。益而不已必决，故受之以《夬》。夬者，决也。决必有遇，故受之以《姤》。</p><p>姤者，遇也。物相遇而后聚，故受之以《萃》。萃者，聚也。聚而上者谓之升，故受之以《升》。升而不已必困，故受之以《困》。困乎上者必反下，故受之以《井》。井道不可不革，故受之以《革》。革物者莫若鼎，故受之以《鼎》。主器者莫若长子，故受之以《震》。震者，动也。物不可以终动，止之，故受之以《艮》。艮者，止也。物不可以终止，故受之以《渐》。渐者，进也。进必有所归，故受之以《归妹》。得其所归者必大，故受之以《丰》。丰者，大也。穷大者必失其居，故受之以《旅》。旅而无所容，故受之以《巽》。巽者，入也。入而后说之，故受之以《兑》。兑者，说也。说而后散之，故受之以《涣》。涣者，离也。物不可以终离，故受之以《节》。节而信之，故受之以《中孚》。有其信者必行之，故受之以《小过》。有过物者必济，故受之以《既济》。物不可穷也，故受之以《未济》，终焉。</p><p>《序卦传》是对《周易》六十四卦的推衍关系的总括。它依据卦名的含义，把《周易》六十四卦看作是一个或相因、或相反的因果联系序列而加以诠释。</p><p>理解《序卦传》可以从以下几个方面入手：</p><ul><li>理解六十四卦的排列次序 ：《序卦传》首先解释了六十四卦的排列顺序，从乾坤两卦开始，到未济卦结束，形成了一个完整的循环。这个排列并非随意，而是基于宇宙间事物发展变化的客观规律。</li></ul><p>理解六十四卦的排列次序 ：</p><ul><li><p>《序卦传》首先解释了六十四卦的排列顺序，从乾坤两卦开始，到未济卦结束，形成了一个完整的循环。这个排列并非随意，而是基于宇宙间事物发展变化的客观规律。</p></li><li><p>掌握卦与卦之间的逻辑关系 ：《序卦传》通过阐述卦名之间的内在联系，展示了六十四卦之间的因果、相因、相反等关系。例如，“物生必蒙，故受之以《蒙》”，说明万物初生之后必然需要启蒙教育，从而引出蒙卦。</p></li></ul><p>掌握卦与卦之间的逻辑关系 ：</p><ul><li><p>《序卦传》通过阐述卦名之间的内在联系，展示了六十四卦之间的因果、相因、相反等关系。例如，“物生必蒙，故受之以《蒙》”，说明万物初生之后必然需要启蒙教育，从而引出蒙卦。</p></li><li><p>领悟事物发展的客观规律 ：《序卦传》通过对六十四卦的推衍，揭示了事物发展变化的客观规律，如物极必反、相反相生等。这些规律不仅适用于自然界，也适用于人类社会和人的内心世界。</p></li></ul><p>领悟事物发展的客观规律 ：</p><ul><li><p>《序卦传》通过对六十四卦的推衍，揭示了事物发展变化的客观规律，如物极必反、相反相生等。这些规律不仅适用于自然界，也适用于人类社会和人的内心世界。</p></li><li><p>结合卦象和卦义进行理解 ：在阅读《序卦传》时，可以结合卦象和卦义进行理解。卦象是六十四卦的图形表示，而卦义则是卦象所蕴含的思想和哲理。将两者结合起来，可以更加深入地理解《序卦传》所阐述的内容。</p></li></ul><p>结合卦象和卦义进行理解 ：</p><ul><li><p>在阅读《序卦传》时，可以结合卦象和卦义进行理解。卦象是六十四卦的图形表示，而卦义则是卦象所蕴含的思想和哲理。将两者结合起来，可以更加深入地理解《序卦传》所阐述的内容。</p></li><li><p>注重实践和应用 ：《序卦传》不仅是理论著作，更是实践指南。通过学习《序卦传》，我们可以将其中所阐述的哲理和思想应用到实际生活中，指导我们的行为和决策。</p></li></ul><p>注重实践和应用 ：</p><ul><li>《序卦传》不仅是理论著作，更是实践指南。通过学习《序卦传》，我们可以将其中所阐述的哲理和思想应用到实际生活中，指导我们的行为和决策。</li></ul>',23)])])}const h=l(t,[["render",s]]);export{d as __pageData,h as default};
